<script lang="ts">
  import * as m from '#lib/paraglide/messages.js';
  import type { FrameMeta } from '#lib/data/types.js';
  let { frames, index = $bindable(0), loaded, playing, speed = $bindable(4), ontoggle, oncommit, onmanual }: { frames: FrameMeta[]; index?: number; loaded: number; playing: boolean; speed?: number; ontoggle: () => void; oncommit: () => void; onmanual: () => void } = $props();
  const span = $derived(Math.max(1e-9,frames.at(-1)!.mjd-frames[0].mjd));
  function step(delta:number){onmanual();index=Math.min(loaded-1,Math.max(0,index+delta));oncommit();}
</script>
<div class="timeline" data-testid="timeline" data-frame-count={loaded}>
  <div class="playback"><button class="primary" onclick={ontoggle} aria-label={playing ? m.pause() : m.play()}>{playing ? 'Ⅱ' : '▶'} <span>{playing ? m.pause() : m.play()}</span></button><button onclick={() => step(-1)} aria-label={m.previous()}>←</button><button onclick={() => step(1)} aria-label={m.next()}>→</button><label class="mono">{m.speed()}<select aria-label={m.speed()} bind:value={speed}>{#each [2,4,6,8,12] as fps}<option value={fps}>{fps} fps</option>{/each}</select></label></div>
  <div class="ruler"><div class="ticks" aria-hidden="true">{#each frames as f, i}<i class:active={i===index} style:left={`${100*(f.mjd-frames[0].mjd)/span}%`} style:height={f.visit!==frames[i-1]?.visit?'18px':'10px'}></i>{/each}</div><input type="range" min="0" max={Math.max(0,loaded-1)} step="1" bind:value={index} aria-label={m.timeline()} oninput={onmanual} onchange={oncommit} onkeydown={e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();step((e.key==='ArrowLeft'?-1:1)*(e.shiftKey?5:1));}}}/><div class="dates mono"><span>{frames[0].date.slice(0,10)}</span><span>{frames.at(-1)!.date.slice(0,10)}</span></div></div>
</div>
<style>.timeline{padding:15px 0;border-bottom:1px solid var(--rule);display:flex;gap:24px;align-items:center}.playback{display:flex;align-items:center;gap:5px}.playback label{display:flex;align-items:center;gap:6px;flex-wrap:wrap;max-width:130px}.playback label select{padding:2px}.ruler{flex:1;min-width:100px;position:relative}.ruler input{width:100%;margin:0;position:relative;z-index:1;opacity:.85}.ticks{height:18px;position:absolute;left:8px;right:8px;top:3px}.ticks i{position:absolute;width:1px;background:var(--graphite)}.ticks i.active{background:var(--co2);width:2px}.dates{display:flex;justify-content:space-between;color:var(--graphite);font-size:10px}@media(max-width:767px){.timeline{gap:10px;flex-wrap:wrap}.playback{width:100%}.playback label{max-width:none;margin-left:auto}.ruler{flex-basis:100%}}</style>
